import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { writeFile } from 'node:fs/promises';
import * as esm from '@everworker/oneringai';
import { ScriptedLoopProvider } from '/Users/aantich/dev/oneringai/examples/agent-loop/scripted-provider.ts';
const require = createRequire(import.meta.url);
const results: unknown[] = [];
for (const [build, api] of [['esm', esm], ['cjs', require('@everworker/oneringai')]] as const) {
  for (const mode of ['run', 'stream', 'disabled', 'override'] as const) {
    const name = `stage10-public-${build}-${mode}`;
    let ready = false, checks = 0, reads = 0;
    const active = mode === 'run' || mode === 'stream';
    const provider = new ScriptedLoopProvider(active ? [
      { text: 'Premature' }, { calls: [{ id: 'read', name: 'read_artifact', args: {} }] }, { text: 'Verified' },
    ] : [{ text: 'Ordinary answer' }]);
    api.Connector.create({ name, vendor: api.Vendor.OpenAI, auth: { type: 'none' }, options: { provider } });
    const agent = api.Agent.create({ connector: name, model: 'gpt-4o-mini', maxIterations: 6,
      context: { model: 'gpt-4o-mini', features: { workingMemory: false, inContextMemory: false } },
      tools: [{ definition: { type: 'function', function: { name: 'read_artifact', parameters: { type: 'object', properties: {} } } }, output: { effect: 'read' }, execute: async () => { ready = true; reads++; return { id: 'A42' }; } }],
      ...(mode === 'disabled' ? {} : { loopPolicy: { completion: context => { checks++; return { complete: ready && context.observations.some(o => o.outcome?.status === 'succeeded') }; } } }),
    });
    try {
      let loop;
      if (mode === 'stream') {
        let completions = 0;
        for await (const event of agent.stream('Verify')) if (event.type === api.StreamEventType.RESPONSE_COMPLETE) { loop = event.loop; completions++; }
        assert.equal(completions, 1);
      } else loop = (await agent.run('Verify', mode === 'override' ? { loopPolicy: null } : undefined)).loop;
      if (active) {
        assert.equal(loop.status, 'completed'); assert.equal(loop.recoveryAttempts, 1);
        assert.equal(checks, 2); assert.equal(reads, 1); assert.equal(provider.requests.length, 3);
        const snapshot = agent.getLoopDiagnostics(); snapshot.reason = 'cancelled';
        assert.equal(agent.getLoopDiagnostics().reason, 'completed');
        assert.equal(agent.context.tools, agent.tools);
      } else { assert.equal(loop, undefined); assert.equal(checks, 0); assert.equal(provider.requests.length, 1); }
      results.push({ build, mode, passed: true, checks, reads, calls: provider.requests.length });
    } finally { agent.destroy(); api.Connector.remove(name); }
  }
}

for (const [build, api] of [['esm', esm], ['cjs', require('@everworker/oneringai')]] as const) {
  for (const mode of ['run', 'stream'] as const) {
    class HostPolicy {
      maxRecoveryAttempts = 0; #checks = 0;
      get checks() { return this.#checks; }
      completion() { this.#checks++; return { complete: false }; }
    }
    const name = `class-${build}-${mode}`, policy = new HostPolicy();
    const provider = new ScriptedLoopProvider([{ text: 'Unchecked candidate' }]);
    api.Connector.create({ name, vendor: api.Vendor.OpenAI, auth: { type: 'none' }, options: { provider } });
    const agent = api.Agent.create({ connector: name, model: 'gpt-4o-mini', loopPolicy: policy, context: { model: 'gpt-4o-mini', features: { workingMemory: false, inContextMemory: false } } });
    try {
      let loop;
      if (mode === 'run') loop = (await agent.run('Verify')).loop;
      else for await (const e of agent.stream('Verify')) if (e.type === api.StreamEventType.RESPONSE_COMPLETE) loop = e.loop;
      assert.equal(loop.reason, 'recovery_exhausted'); assert.equal(policy.checks, 1); assert.equal(provider.requests.length, 1);
      results.push({ build, mode: `class-${mode}`, passed: true, checks: policy.checks });
    } finally { agent.destroy(); api.Connector.remove(name); }
  }
  for (const mode of ['run', 'stream'] as const) {
    const name = `stopped-${build}-${mode}`; let writes = 0;
    const provider = new ScriptedLoopProvider([{ calls: [{ id: 'call', name: 'submit', args: { job: 'A42' } }] }, ...(mode === 'run' ? [{ text: '{"message":"Stopped"}' }] : []), { text: 'Continue' }]);
    api.Connector.create({ name, vendor: api.Vendor.OpenAI, auth: { type: 'none' }, options: { provider } });
    const agent = api.Agent.create({ connector: name, model: 'gpt-4o-mini', loopPolicy: {}, maxIterations: 1, context: { model: 'gpt-4o-mini', features: { workingMemory: false, inContextMemory: false } }, tools: [{ definition: { type: 'function', function: { name: 'submit', parameters: { type: 'object', properties: {} } } }, output: { effect: 'write' }, execute: async () => { writes++; return 'PUBLIC_RAW_A42'; } }] });
    try {
      let loop;
      if (mode === 'run') loop = (await agent.run('Submit once', { responseFormat: { type: 'json_object' } })).loop;
      else for await (const e of agent.stream('Submit once')) if (e.type === api.StreamEventType.RESPONSE_COMPLETE) loop = e.loop;
      assert.equal(loop.reason, 'iteration_limit'); assert.equal(agent.context.getCurrentInput().length, 0);
      await agent.run('Resume', { loopPolicy: null });
      assert.ok(JSON.stringify(provider.requests.at(-1).input).includes('PUBLIC_RAW_A42')); assert.equal(writes, 1);
      results.push({ build, mode: `stopped-${mode}`, passed: true, writes });
    } finally { agent.destroy(); api.Connector.remove(name); }
  }
}
await writeFile('/tmp/oneringai-stage10-corrections-final-public.json', JSON.stringify(results, null, 2) + '\n');
console.log(JSON.stringify(results));
